begin;
create extension if not exists pgtap with schema extensions;
select plan(30);
select has_table('public','families','families exist');
select has_table('public','people','people exist');
select has_table('public','family_members','members exist');
select has_table('public','cases','cases exist');
select has_table('public','case_categories','categories exist');
insert into auth.users(id) select ('30000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,3) n;
insert into auth.sessions(id,user_id,created_at,updated_at) select ('40000000-0000-0000-0000-00000000000' || n)::uuid, ('30000000-0000-0000-0000-00000000000' || n)::uuid, now(), now() from generate_series(1,3) n;
insert into public.employees(id,employee_code,display_name,role) values ('50000000-0000-0000-0000-000000000001','CASEW','Writer','employee'),('50000000-0000-0000-0000-000000000002','CASER','Reader','employee'),('50000000-0000-0000-0000-000000000003','CASEN','None','employee');
insert into private.employee_auth(employee_id,auth_user_id) select ('50000000-0000-0000-0000-00000000000' || n)::uuid, ('30000000-0000-0000-0000-00000000000' || n)::uuid from generate_series(1,3) n;
insert into public.employee_permissions(employee_id,cases_write,cases_read) values ('50000000-0000-0000-0000-000000000001',true,false),('50000000-0000-0000-0000-000000000002',false,true);
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000001","session_id":"40000000-0000-0000-0000-000000000001","role":"authenticated"}',true);
set local role authenticated;
select lives_ok($$insert into public.families(name) values ('أسرة وهمية'),('أسرة أخرى')$$,'writer inserts families');
select is((select count(distinct code)::int from public.families),2,'generated codes unique in one statement');
select ok((select min(code) from public.families) like 'F-%','code has approved prefix');
select throws_ok($$update public.families set code='F-0001'$$,'42501',null,'code cannot be updated');
select throws_ok($$insert into public.families(name,code) values ('x','F-0001')$$,'42501',null,'code cannot be supplied');
select throws_ok($$delete from public.families$$,'42501',null,'family code history cannot be deleted');
select lives_ok($$select public.add_family_member((select id from public.families limit 1),'شخص وهمي','ابن')$$,'writer adds household member');
select is((select count(*)::int from public.family_members),1,'membership saved');
select lives_ok($$select public.save_case(null,(select id from public.families limit 1),'ملاحظات',array['هجر','يتيم الأم'])$$,'writer adds case with multiple categories');
select is((select count(*)::int from public.case_categories),2,'both categories persisted');
select throws_ok($$select public.save_case(null,(select id from public.families limit 1),'',array['غير معروف'])$$,'23514',null,'unknown category rejected');
select is((select count(*)::int from public.cases),1,'invalid case rolls back');
select lives_ok($$select public.save_case((select id from public.cases limit 1),(select family_id from public.cases limit 1),'تم التعديل',array['يتيم الأب','مطلقة'])$$,'writer updates a case');
select is((select string_agg(category,',' order by category) from public.case_categories),'مطلقة,يتيم الأب','case categories replaced together');
select throws_ok($$select public.save_case(null,(select id from public.families limit 1),'',array['وفاة'])$$,'23514',null,'removed category rejected for new records');
select throws_ok($$select public.save_case((select id from public.cases limit 1),(select family_id from public.cases limit 1),'lost',array['غير معروف'])$$,'23514',null,'invalid edit rejected');
select is((select notes from public.cases limit 1),'تم التعديل','failed edit preserves original case');
reset role;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000002","session_id":"40000000-0000-0000-0000-000000000002","role":"authenticated"}',true);
set local role authenticated;
select is((select count(*)::int from public.families),2,'reader sees families');
select is((select count(*)::int from public.people),1,'reader sees people');
select is((select count(*)::int from public.family_members),1,'reader sees members');
select is((select count(*)::int from public.cases),1,'reader sees cases');
select is((select count(*)::int from public.case_categories),2,'reader sees categories');
select throws_ok($$insert into public.families(name) values ('x')$$,'42501',null,'reader cannot insert');
select throws_ok($$select public.save_case(null,(select id from public.families limit 1),'',array['هجر'])$$,'42501',null,'reader cannot save case');
reset role;
select set_config('request.jwt.claims','{"sub":"30000000-0000-0000-0000-000000000003","session_id":"40000000-0000-0000-0000-000000000003","role":"authenticated"}',true);
set local role authenticated;
select is((select (select count(*) from public.families)+(select count(*) from public.people)+(select count(*) from public.family_members)+(select count(*) from public.cases)+(select count(*) from public.case_categories))::int,0,'unprivileged user sees no domain rows');
select * from finish(); rollback;
